use iterators::{Status, Ticket, TicketStore};
use ticket_fields::test_helpers::{ticket_description, ticket_title};

#[test]
fn rust_tutor_hidden_iterator_preserves_order() {
    let mut store = TicketStore::new();
    for status in [Status::ToDo, Status::InProgress, Status::Done] {
        store.add_ticket(Ticket { title: ticket_title(), description: ticket_description(), status });
    }
    let statuses: Vec<_> = store.into_iter().map(|ticket| ticket.status).collect();
    assert_eq!(statuses, [Status::ToDo, Status::InProgress, Status::Done]);
}

use rwlock::data::TicketDraft;
use rwlock::launch;
use ticket_fields::test_helpers::{ticket_description, ticket_title};

#[test]
fn rust_tutor_hidden_rwlock_allows_two_readers() {
    let client = launch(5);
    let id = client.insert(TicketDraft { title: ticket_title(), description: ticket_description() }).unwrap();
    let ticket = client.get(id).unwrap().unwrap();
    let first = ticket.read().unwrap();
    let second = ticket.try_read().expect("a read lock must not exclude another reader");
    assert_eq!(first.id, second.id);
}

