use rwlock::data::{Status, TicketDraft};
use rwlock::launch;
use ticket_fields::test_helpers::{ticket_description, ticket_title};

#[test]
fn rust_tutor_regression_rwlock_write_after_read() {
    let client = launch(5);
    let id = client.insert(TicketDraft { title: ticket_title(), description: ticket_description() }).unwrap();
    let ticket = client.get(id).unwrap().unwrap();
    { assert_eq!(ticket.read().unwrap().status, Status::ToDo); }
    ticket.write().unwrap().status = Status::Done;
    assert_eq!(ticket.read().unwrap().status, Status::Done);
}

