use cancellation::run;
use std::time::Duration;
use tokio::io::AsyncWriteExt;
use tokio::net::{TcpListener, TcpStream};

#[tokio::test]
async fn rust_tutor_hidden_cancellation_keeps_partial_bytes() {
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let handle = tokio::spawn(run(listener, 1, Duration::from_millis(40)));
    let mut stream = TcpStream::connect(address).await.unwrap();
    stream.write_all(b"partial").await.unwrap();
    tokio::time::sleep(Duration::from_millis(100)).await;
    let buffered = handle.await.unwrap();
    assert_eq!(buffered, b"partial");
}

